  "並": {"ja": "並んでお待ちください。", "en": "Wait in line, please.", "jaId": 83523, "enId": 320193, "jaAuthor": "small_snow", "enAuthor": "CK", "furigana": "[並|なら]んでお[待|ま]ちください。", "reading": "ならんでおまちください。", "furiganaAuthor": "small_snow", "why": ["inBand", "furigana", "nativeAuthor", "ratedOk", "glossInEnglish"]},
  "丸": {"ja": "丸一日教えていたのでへとへとだった。", "en": "I was exhausted by a full day's teaching.", "jaId": 183686, "enId": 20809, "jaAuthor": "KK_kaku_", "enAuthor": "al_ex_an_der", "furigana": "[丸|まる][一|いち][日|にち][教|おし]えていたのでへとへとだった。", "reading": "まるいちにちおしえていたのでへとへとだった。", "furiganaAuthor": "KK_kaku_", "why": ["inBand", "furigana", "nativeAuthor", "ratedOk", "glossInEnglish"]},
  "久": {"ja": "昨日、久しぶりにそれをしたよ。", "en": "I did that yesterday for the first time in a long time.", "jaId": 8924573, "enId": 6230267, "jaAuthor": "small_snow", "enAuthor": "CK", "furigana": "[昨日|きのう]、[久|ひさ]しぶりにそれをしたよ。", "reading": "きのう、ひさしぶりにそれをしたよ。", "furiganaAuthor": "small_snow", "why": ["inBand", "furigana", "nativeAuthor", "ratedOk", "glossInEnglish"]},
  "乱": {"ja": "庭には様々な花が咲き乱れていた。", "en": "The garden was a riot of color.", "jaId": 125517, "enId": 278475, "jaAuthor": "tommy_san", "enAuthor": "AlanF_US", "furigana": "[庭|にわ]には[様々|さまざま]な[花|はな]が[咲|さ]き[乱|みだ]れていた。", "reading": "にわにはさまざまなはながさきみだれていた。", "furiganaAuthor": "", "why": ["inBand", "furigana", "nativeAuthor", "ratedOk", "glossInEnglish"]},
  "乳": {"ja": "牛乳を飲みますか。", "en": "Do you drink milk?", "jaId": 182264, "enId": 5360666, "jaAuthor": "KK_kaku_", "enAuthor": "CarpeLanam", "furigana": "[牛乳|ぎゅう|にゅう]を[飲|の]みますか。", "reading": "ぎゅうにゅうをのみますか。", "furiganaAuthor": "KK_kaku_", "why": ["inBand", "furigana", "nativeAuthor", "ratedOk", "glossInEnglish"]},
  "乾": {"ja": "服はまだ乾いてないよ。", "en": "The clothes aren't dry yet.", "jaId": 10151303, "enId": 10151255, "jaAuthor": "small_snow", "enAuthor": "CK", "furigana": "[服|ふく]はまだ[乾|かわ]いてないよ。", "reading": "ふくはまだかわいてないよ。", "furiganaAuthor": "small_snow", "why": ["inBand", "furigana", "nativeAuthor", "ratedOk", "glossInEnglish"]},
  "了": {"ja": "私の仕事は完了しました。", "en": "My work is finished.", "jaId": 9825488, "enId": 250935, "jaAuthor": "bunbuku", "enAuthor": "CK", "furigana": "[私|わたし]の[仕事|し|ごと]は[完了|かん|りょう]しました。", "reading": "わたしのしごとはかんりょうしました。", "furiganaAuthor": "bunbuku", "why": ["inBand", "furigana", "nativeAuthor", "ratedOk", "glossInEnglish"]},
  "介": {"ja": "かわいい子紹介してよ。", "en": "Introduce me to a cute girl.", "jaId": 3677771, "enId": 9234986, "jaAuthor": "tommy_san", "enAuthor": "kedymera", "furigana": "かわいい[子|こ][紹介|しょう|かい]してよ。", "reading": "かわいいこしょうかいしてよ。", "furiganaAuthor": "small_snow", "why": ["inBand", "furigana", "nativeAuthor", "ratedOk"]},
  "仏": {"ja": "仏教はインドで始まった。", "en": "Buddhism originated in India.", "jaId": 8910153, "enId": 4875904, "jaAuthor": "bunbuku", "enAuthor": "AlanF_US", "furigana": "[仏|ふっ][教|きょう]はインドで[始|はじ]まった。", "reading": "ふっきょうはインドではじまった。", "furiganaAuthor": "fjay69", "why": ["inBand", "furigana", "nativeAuthor", "ratedOk", "glossInEnglish"]},
  "令": {"ja": "私の命令は絶対だ。", "en": "My orders are absolute.", "jaId": 162529, "enId": 251985, "jaAuthor": "bunbuku", "enAuthor": "Dejo", "furigana": "[私|わたし]の[命令|めい|れい]は[絶対|ぜっ|たい]だ。", "reading": "わたしのめいれいはぜったいだ。", "furiganaAuthor": "bunbuku", "why": ["inBand", "furigana", "nativeAuthor", "glossInEnglish"]},
