  "伸": {"ja": "私は足を伸ばした。", "en": "I stretched out my legs.", "jaId": 2139090, "enId": 1887694, "jaAuthor": "bunbuku", "enAuthor": "CK", "furigana": "[私|わたし]は[足|あし]を[伸|の]ばした。", "reading": "わたしはあしをのばした。", "furiganaAuthor": "KK_kaku_", "why": ["inBand", "furigana", "nativeAuthor", "ratedOk", "glossInEnglish"]},
  "伺": {"ja": "もし必要があれば伺います。", "en": "If there's anything I need, I'll ask.", "jaId": 4212059, "enId": 9235117, "jaAuthor": "small_snow", "enAuthor": "kedymera", "furigana": "もし[必要|ひつ|よう]があれば[伺|うかが]います。", "reading": "もしひつようがあればうかがいます。", "furiganaAuthor": "Yorwba", "why": ["inBand", "furigana", "nativeAuthor", "ratedOk", "glossInEnglish"]},
  "低": {"ja": "今日の最低気温は３℃だった。", "en": "Today's low was 3 degrees Celsius.", "jaId": 171910, "enId": 1422370, "jaAuthor": "bunbuku", "enAuthor": "CK", "furigana": "[今日|きょう]の[最低|さい|てい][気温|き|おん]は[３|さん][℃|ど]だった。", "reading": "きょうのさいていきおんはさんどだった。", "furiganaAuthor": "bunbuku", "why": ["inBand", "furigana", "nativeAuthor", "ratedOk", "glossInEnglish"]},
  "依": {"ja": "ご依頼の件、承知しました。", "en": "I am willing to agree to your request.", "jaId": 217219, "enId": 54527, "jaAuthor": "small_snow", "enAuthor": "CM", "furigana": "ご[依頼|い|らい]の[件|けん]、[承知|しょう|ち]しました。", "reading": "ごいらいのけん、しょうちしました。", "furiganaAuthor": "small_snow", "why": ["inBand", "furigana", "nativeAuthor", "ratedOk", "glossInEnglish"]},
