  "倍": {"ja": "８は２の４倍です。", "en": "Eight is four times two.", "jaId": 9237705, "enId": 9232865, "jaAuthor": "small_snow", "enAuthor": "CK", "furigana": "[８|はち]は[２|に]の[４|よん][倍|ばい]です。", "reading": "はちはにのよんばいです。", "furiganaAuthor": "small_snow", "why": ["inBand", "furigana", "nativeAuthor", "ratedOk", "glossInEnglish"]},
  "停": {"ja": "バス停まで走った。", "en": "I ran to the bus stop.", "jaId": 8887754, "enId": 8887746, "jaAuthor": "small_snow", "enAuthor": "CK", "furigana": "バス[停|てい]まで[走|はし]った。", "reading": "バスていまではしった。", "furiganaAuthor": "small_snow", "why": ["inBand", "furigana", "nativeAuthor", "ratedOk"]},
  "傾": {"ja": "晩婚化傾向は今後もますます進みそうだ。", "en": "The trend towards late marriage is going to increase more and more.", "jaId": 121182, "enId": 282825, "jaAuthor": "KK_kaku_", "enAuthor": null, "furigana": "[晩婚|ばん|こん][化|か][傾向|けい|こう]は[今後|こん|ご]もますます[進|すす]みそうだ。", "reading": "ばんこんかけいこうはこんごもますますすすみそうだ。", "furiganaAuthor": "KK_kaku_", "why": ["inBand", "furigana", "nativeAuthor", "ratedOk", "glossInEnglish"]},
  "像": {"ja": "この画像、解像度が低すぎてすごく汚い。", "en": "The image quality is really bad - the resolution is so low.", "jaId": 222693, "enId": 60023, "jaAuthor": "KK_kaku_", "enAuthor": null, "furigana": "この[画像|が|ぞう]、[解像度|かい|ぞう|ど]が[低|ひく]すぎてすごく[汚|きたな]い。", "reading": "このがぞう、かいぞうどがひくすぎてすごくきたない。", "furiganaAuthor": "KK_kaku_", "why": ["inBand", "furigana", "nativeAuthor", "ratedOk", "glossInEnglish"]},
  "億": {"ja": "損害額は１億ドルになるだろう。", "en": "The loss will amount to one hundred million dollars.", "jaId": 139331, "enId": 8815398, "jaAuthor": "small_snow", "enAuthor": "CK", "furigana": "[損害|そん|がい][額|がく]は[１|いち][億|おく]ドルになるだろう。", "reading": "そんがいがくはいちおくドルになるだろう。", "furiganaAuthor": "small_snow", "why": ["inBand", "furigana", "nativeAuthor", "ratedOk", "glossInEnglish"]},
