  "児": {"ja": "図書館にはたくさんの児童書がある。", "en": "We have a lot of children's books in the library.", "jaId": 143879, "enId": 270687, "jaAuthor": "bunbuku", "enAuthor": "CK", "furigana": "[図書館|と|しょ|かん]にはたくさんの[児童|じ|どう][書|しょ]がある。", "reading": "としょかんにはたくさんのじどうしょがある。", "furiganaAuthor": "bunbuku", "why": ["inBand", "furigana", "nativeAuthor", "glossInEnglish"]},
