  "効": {"ja": "薬の効果は消えていた。", "en": "The effect of the drug had worn off.", "jaId": 79488, "enId": 324230, "jaAuthor": "bunbuku", "enAuthor": "CK", "furigana": "[薬|くすり]の[効果|こう|か]は[消|き]えていた。", "reading": "くすりのこうかはきえていた。", "furiganaAuthor": "bunbuku", "why": ["inBand", "furigana", "nativeAuthor", "ratedOk", "glossInEnglish"]},
